// This file is generated by AI.

// `editor/scripts/` 下三个类名护栏共用的目录遍历。
//
// 只做一件事: 递归列出 `editor/src` 下的**文件**绝对路径, 并跳过生成物目录与无关目录。
// 各脚本自己决定读哪些扩展名、读出来做什么。

import { readdirSync, statSync } from 'node:fs';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';

/** 这些目录不参与扫描: 前两个是生成物, 后两个在编辑器源码树下本来也不会有。 */
const SKIPPED_DIRS = new Set(['node_modules', '.svelte-kit', 'dist', '.git']);

/** `editor/` 的绝对路径 (无论从哪个脚本调用)。 */
export const editorRoot = fileURLToPath(new URL('..', import.meta.url));

/** 递归列出 `dir` 下所有文件的绝对路径。 */
export function walkFiles(dir, out = []) {
  for (const name of readdirSync(dir)) {
    if (SKIPPED_DIRS.has(name)) continue;
    const full = join(dir, name);
    if (statSync(full).isDirectory()) walkFiles(full, out);
    else out.push(full);
  }
  return out;
}
